import heapq

def match(orders):
    trades = []
    book = {}  # id -> {'side','price','qty','ts','active'}
    buy_heap = []  # (-price, ts, id) max-heap on price
    sell_heap = []  # (price, ts, id) min-heap on price
    ts_counter = 0

    def clean_buy():
        while buy_heap:
            negp, ts, oid = buy_heap[0]
            info = book.get(oid)
            if info is None or not info['active'] or info['qty'] <= 0:
                heapq.heappop(buy_heap)
            else:
                break

    def clean_sell():
        while sell_heap:
            p, ts, oid = sell_heap[0]
            info = book.get(oid)
            if info is None or not info['active'] or info['qty'] <= 0:
                heapq.heappop(sell_heap)
            else:
                break

    for order in orders:
        ts_counter += 1
        typ = order[0]

        if typ == 'cancel':
            oid = order[1]
            info = book.get(oid)
            if info is not None and info['active'] and info['qty'] > 0:
                info['active'] = False
            continue

        if typ == 'market':
            _, oid, side, qty = order
            price = None
        else:
            _, oid, side, price, qty = order

        remaining = qty

        if side == 'buy':
            while remaining > 0:
                clean_sell()
                if not sell_heap:
                    break
                sp, sts, sid = sell_heap[0]
                if typ != 'market' and sp > price:
                    break
                sorder = book[sid]
                trade_qty = min(remaining, sorder['qty'])
                trades.append([oid, sid, sp, trade_qty])
                remaining -= trade_qty
                sorder['qty'] -= trade_qty
                if sorder['qty'] == 0:
                    heapq.heappop(sell_heap)
                    sorder['active'] = False

            if typ == 'limit' and remaining > 0:
                book[oid] = {'side': 'buy', 'price': price, 'qty': remaining,
                              'ts': ts_counter, 'active': True}
                heapq.heappush(buy_heap, (-price, ts_counter, oid))

        else:  # sell
            while remaining > 0:
                clean_buy()
                if not buy_heap:
                    break
                negp, bts, bid = buy_heap[0]
                bp = -negp
                if typ != 'market' and bp < price:
                    break
                border = book[bid]
                trade_qty = min(remaining, border['qty'])
                trades.append([bid, oid, bp, trade_qty])
                remaining -= trade_qty
                border['qty'] -= trade_qty
                if border['qty'] == 0:
                    heapq.heappop(buy_heap)
                    border['active'] = False

            if typ == 'limit' and remaining > 0:
                book[oid] = {'side': 'sell', 'price': price, 'qty': remaining,
                              'ts': ts_counter, 'active': True}
                heapq.heappush(sell_heap, (price, ts_counter, oid))

    return trades

